function csvParse(t){let a=[],r=[],v='',q=false;for(let i=0;i<t.length;i++){let c=t[i],n=t[i+1];if(q){if(c=='"'&&n=='"'){v+='"';i++}else if(c=='"')q=false;else v+=c}else if(c=='"')q=true;else if(c==','){r.push(v);v=''}else if(c=='\n'){r.push(v.replace(/\r$/,''));a.push(r);r=[];v=''}else v+=c}if(v||r.length){r.push(v);a.push(r)}let h=a.shift();return a.filter(x=>x.length>1).map(x=>Object.fromEntries(h.map((k,i)=>[k,x[i]??''])))}function n(v){let x=+v;return Number.isFinite(x)?x:0}
function transfers(){return rows.filter(r=>r.Record_Type==='Transfer relationship')}function fees(){return rows.filter(r=>r.Record_Type.includes('in-lieu')||r.Record_Type==='Aggregate in-lieu account')}function programs(){let m={};rows.forEach(r=>{let p=r.Program||'Unknown';m[p]=(m[p]||0)+1});return m}function counts(field,src=rows){let m={};src.forEach(r=>{let k=r[field]||'Unknown';m[k]=(m[k]||0)+1});return m}
