function overview(){let ts=transfers(),known=ts.filter(r=>r.Sender_Latitude&&r.Receiver_Latitude),ons=rows.filter(r=>r.Record_Type==='On-site obligation'),fs=fees();view.innerHTML='<div class="hero-grid"><div class="card story"><h2>The permit address is not always the delivery address.</h2><p>This dashboard follows the <strong>relationship</strong> between the development that creates an affordable-housing obligation and the place where that obligation is recorded as satisfied. It separates entitlement geography from delivery geography—and preserves what the public record still does not establish.</p><div class="purpose-flow"><div><b>1 · Origin</b>Development receives a regulatory benefit</div><span class="arrow">→</span><div><b>2 · Compliance</b>On-site · off-site · in-lieu</div><span class="arrow">→</span><div><b>3 · Delivery</b>Where affordable housing is recorded to land</div></div></div><div class="kpis"><div class="kpi"><div class="n">'+rows.length+'</div><div class="l">ledger records preserved</div></div><div class="kpi"><div class="n">'+ts.length+'</div><div class="l">transfer relationships</div></div><div class="kpi"><div class="n">'+ons.length+'</div><div class="l">on-site contrasts</div></div><div class="kpi"><div class="n">'+fs.length+'</div><div class="l">in-lieu evidence records</div></div></div></div><div class="grid2"><div class="card"><div class="section-title"><div><h3>Programs represented</h3><p>Every program in the ledger, not only the default filter.</p></div></div>'+bars(programs())+'</div><div class="card"><div class="section-title"><div><h3>Evidence is part of the finding</h3><p>Confirmed, candidate and conflicting records remain distinct.</p></div></div>'+bars(counts('Evidence_Status'))+'</div></div><div class="card" style="margin-top:16px"><div class="section-title"><div><h2>Trace one obligation</h2><p>Select a sender and see the receiving site and evidence together.</p></div></div>'+picker()+relationship(ts.find(r=>r.Relationship_ID===focus)||ts[0])+'</div>';bindPick()}
function bindPick(){let p=document.getElementById('relpick');if(p)p.onchange=()=>{focus=p.value;render()}}
function relationships(){let ts=transfers();view.innerHTML='<div class="card"><div class="section-title"><div><h2>Sender → receiver relationships</h2><p>The relationship—not the permit—is the primary record.</p></div></div>'+picker()+relationship(ts.find(r=>r.Relationship_ID===focus)||ts[0])+'</div><div class="grid2"><div class="card"><h3>Compliance pathways</h3>'+bars(counts('Compliance_Pathway',ts))+'</div><div class="card"><h3>Relationship status</h3>'+bars(counts('Relationship_Status',ts),'mint')+'</div></div>';bindPick()}
function geography(){view.innerHTML='<div class="card"><div class="section-title"><div><h2>Geography of compliance</h2><p>Road-based San Diego map at geographic scale. Lines connect documented/candidate sending and receiving coordinates.</p></div></div>'+picker()+'<div id="map"></div></div>';bindPick();setTimeout(drawMap,0)}
function drawMap(){if(map){map.remove()}map=L.map('map',{scrollWheelZoom:false}).setView([32.79,-117.15],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors'}).addTo(map);let bounds=[];transfers().forEach(r=>{let a=[+r.Sender_Latitude,+r.Sender_Longitude],b=[+r.Receiver_Latitude,+r.Receiver_Longitude];if(a.every(Number.isFinite)){L.circleMarker(a,{radius:7,color:'#e2b448',fillColor:'#e2b448',fillOpacity:.9,weight:2}).bindPopup('<b>Sender</b><br>'+esc(r.Sender_Project_Name||r.Project_Name)+'<br>'+esc(r.Program)).addTo(map);bounds.push(a)}if(b.every(Number.isFinite)){L.circleMarker(b,{radius:8,color:'#4f8e7a',fillColor:'#83c6af',fillOpacity:.95,weight:2}).bindPopup('<b>Receiver</b><br>'+esc(r.Receiver_Project_Name||r.Receiver_Address)).addTo(map);bounds.push(b)}if(a.every(Number.isFinite)&&b.every(Number.isFinite)){L.polyline([a,b],{color:r.Relationship_ID===focus?'#d77a61':'#637675',weight:r.Relationship_ID===focus?5:2,opacity:r.Relationship_ID===focus?1:.65,dashArray:r.Evidence_Status==='Verified'?null:'7 7'}).bindPopup('<b>'+esc(r.Relationship_ID)+'</b><br>'+esc(r.Sender_Project_Name||r.Project_Name)+' → '+esc(r.Receiver_Project_Name||r.Receiver_Address)+'<br>'+esc(r.Units_Transferred||r.Units_Recorded||'?')+' units · '+esc(r.Evidence_Status)).addTo(map)}});if(bounds.length)map.fitBounds(bounds,{padding:[30,30]});let leg=L.control({position:'bottomright'});leg.onAdd=()=>{let d=L.DomUtil.create('div','maplegend');d.innerHTML='<b>Map legend</b><br><i style="background:#e2b448"></i>Sending project<br><i style="background:#83c6af"></i>Receiving site<br><span style="color:#9aa">━━</span> verified/recorded link<br><span style="color:#9aa">┄┄</span> candidate/conflicting link<br><span style="color:#d77a61">━━</span> selected relationship';return d};leg.addTo(map)}
function programsView(){let ps=programs();view.innerHTML='<div class="grid2"><div class="card"><div class="section-title"><div><h2>Programs in the evidence</h2><p>Record counts reflect ledger evidence, not program-wide production totals.</p></div></div>'+bars(ps)+'</div><div class="card"><h2>Program × compliance pathway</h2><div class="tablewrap"><table><thead><tr><th>Program</th><th>On-site</th><th>Off-site / receiving</th><th>In-lieu</th></tr></thead><tbody>'+Object.keys(ps).map(p=>{let rr=rows.filter(r=>r.Program===p);return '<tr><td><b>'+esc(p)+'</b></td><td>'+rr.filter(r=>r.Compliance_Pathway==='On-site').length+'</td><td>'+rr.filter(r=>/Off-site|Receiving/.test(r.Compliance_Pathway)).length+'</td><td>'+rr.filter(r=>r.Compliance_Pathway==='In-lieu fee').length+'</td></tr>'}).join('')+'</tbody></table></div></div></div><div class="card" style="margin-top:16px"><h2>Why program distinctions matter</h2><p class="callout">A program label does not itself prove where units were delivered. The dashboard therefore keeps <b>Origin Program</b>, <b>Receiver Program</b>, compliance pathway and evidence status separate—especially where the City record conflicts, as with the Denizen/The Bel entry.</p></div>'}
function feesView(){let f=fees();view.innerHTML='<div class="hero-grid"><div class="card story"><h2>Fees are a compliance pathway—not a receiving address.</h2><p>The ledger contains fee language and an aggregate 2024 account, but most payer-level records do <strong>not</strong> establish a downstream project where the money produced housing. The dashboard therefore does not invent geographic connections.</p></div><div class="kpis"><div class="kpi"><div class="n">'+f.length+'</div><div class="l">fee evidence records</div></div><div class="kpi"><div class="n">'+f.filter(r=>r.Evidence_Status==='Verified').length+'</div><div class="l">verified aggregate/account records</div></div></div></div><div class="grid2"><div class="card"><h3>Fee evidence by program</h3>'+bars(counts('Origin_Program',f))+'</div><div class="card"><h3>Evidence status</h3>'+bars(counts('Evidence_Status',f))+'</div></div>'+table(f)}
function evidence(){view.innerHTML='<div class="grid2"><div class="card"><h2>Evidence states</h2>'+bars(counts('Evidence_Status'))+'</div><div class="card"><h2>Confidence</h2>'+bars(counts('Confidence'))+'</div></div><div class="card" style="margin-top:16px"><h2>Interpretation rule</h2><p class="callout">This dashboard evaluates where an affordable-housing obligation is recorded as satisfied: on-site, at a documented receiving site, or through fee evidence. Occupancy is not used to classify compliance.</p></div>'}
function table(src=rows){let cols=['Relationship_ID','Record_Type','Project_Name','Sender_Project_Name','Receiver_Project_Name','Program','Compliance_Pathway','Units_Recorded','Evidence_Status','Relationship_Status'];return '<div class="card" style="margin-top:16px"><div class="section-title"><div><h2>Inspect the records</h2><p>Exact evidence remains available below the visuals.</p></div></div><div class="tablewrap"><table><thead><tr>'+cols.map(c=>'<th>'+esc(c.replaceAll('_',' '))+'</th>').join('')+'</tr></thead><tbody>'+src.map(r=>'<tr data-record-id="'+esc(r.Relationship_ID)+'">'+cols.map(c=>'<td>'+esc(r[c])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></div>'}
function ledger(){view.innerHTML='<div class="card"><div class="section-title"><div><h2>Master relationship ledger</h2><p>All <span data-testid="ledger-count">'+rows.length+'</span> records are preserved. Unknown values remain unknown.</p></div><div class="selectrow"><label>Ledger evidence state <select id="estate"><option value="">All</option>'+['Verified','Conflicting','Candidate','Unresolved'].map(x=>'<option>'+x+'</option>').join('')+'</select></label><label>Search ledger <input id="search" aria-label="Search ledger" placeholder="Search records…"></label><button class="btn" id="reset">Reset ledger</button><button class="btn" id="export">Export ledger CSV</button></div></div></div><div id="tbl">'+table(rows)+'</div>';const search=document.getElementById('search'),estate=document.getElementById('estate'),tbl=document.getElementById('tbl'),reset=document.getElementById('reset');let apply=()=>{let q=search.value.toLowerCase(),st=estate.value;tbl.innerHTML=table(rows.filter(r=>(!st||r.Evidence_Status===st)&&(!q||Object.values(r).join(' ').toLowerCase().includes(q))))};search.oninput=apply;estate.setAttribute('aria-label','Ledger evidence state');estate.onchange=apply;reset.onclick=()=>{search.value='';estate.value='';apply()};document.getElementById('export').onclick=downloadCurrentLedger}
function render(){if(map){map.stop();map.remove();map=null}nav();history.replaceState(null,'','?tab='+tab+(focus?'&focus='+encodeURIComponent(JSON.stringify({relationshipId:focus})):'') );({overview,relationships,geography,programs:programsView,fees:feesView,evidence,ledger}[tab]||overview)()}
const COLORS={Verified:'#67c5a7',Conflicting:'#ed9a82',Candidate:'#c98e73',Unresolved:'#b2bac4'};
let evidenceData={},communityData,geoLayers=[],geoMarkers=[];
const stateBadge=s=>`<span class="state" style="--state:${COLORS[s]||COLORS.Unresolved}">${esc(s||'Unresolved')}</span>`;
function coord(r,role){const a=r[role+'_Latitude'],b=r[role+'_Longitude'];if(a==null||b==null||String(a).trim()===''||String(b).trim()==='')return null;const lat=Number(a),lon=Number(b);return Number.isFinite(lat)&&Number.isFinite(lon)&&lat>32&&lat<34&&lon>-118&&lon<-116?[lat,lon]:null}
function miles(a,b){const rad=Math.PI/180,dlat=(b[0]-a[0])*rad,dlon=(b[1]-a[1])*rad,h=Math.sin(dlat/2)**2+Math.cos(a[0]*rad)*Math.cos(b[0]*rad)*Math.sin(dlon/2)**2;return 3958.7613*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
function spatial(r){const a=coord(r,'Sender'),b=coord(r,'Receiver');if(r.Relationship_ID==='P2B-T-004')return 'Distance withheld: the stored Twain sender coordinate conflicts with its Navajo address context.';return a&&b?miles(a,b).toFixed(2)+' miles straight-line (not a travel route)':'Distance unknown — '+(!a?'sender':'receiver')+' coordinates missing.'}
function unitLabel(r){if(r.Research_Sender_Name)return 'Individual allocation unknown · group total 41';if(r.Relationship_ID==='P2B-T-005')return '41 reported units · group total';const v=r.Units_Transferred||r.Units_Recorded;return v!==''&&v!=null?esc(v)+' listed units':'Listed-unit count unknown'}
function fields(o){return '<dl class="record-fields">'+Object.entries(o||{}).filter(([k,v])=>v!==null&&v!==''&&v!==undefined).map(([k,v])=>'<dt>'+esc(k.replaceAll('_',' '))+'</dt><dd>'+esc(typeof v==='object'?JSON.stringify(v):v)+'</dd>').join('')+'</dl>'}
function sourceDetails(r){let ev=(evidenceData.evidence_register||[]).filter(e=>e.Relationship_ID===r.Relationship_ID);let ids=new Set((String(r.Source_Links||'')+';'+ev.map(e=>e.Source_ID).join(';')).match(/SRC-[A-Z0-9-]+/g)||[]);let sources=(evidenceData.source_register||[]).filter(s=>ids.has(s.Source_ID));let fee=(evidenceData.fee_evidence||[]).find(f=>r.Relationship_ID===f.Fee_Record_ID||r.Relationship_ID.endsWith(f.Fee_Record_ID));let html='<details class="sources"><summary>Inspect source records · '+esc(r.Relationship_ID)+'</summary><p>These are preserved research and source extracts, not new findings. Blank source fields remain unknown.</p>'+fields({Evidence_Summary:r.Evidence_Summary,Research_Notes:r.Research_Notes,Source_Links:r.Source_Links,Discrepancy_IDs:r.Discrepancy_IDs});if(fee)html+='<h4>Fee source extract</h4>'+fields(fee);html+=ev.map(e=>'<details><summary>'+esc(e.Evidence_ID+' · '+(e.Source_Record||e.Source_ID))+'</summary>'+fields(e)+'</details>').join('');html+=sources.map(s=>'<details><summary>'+esc(s.Source_ID+' · '+s.Category)+'</summary>'+fields(s)+'</details>').join('');if(/HCR23-058/.test(JSON.stringify(r)+JSON.stringify(ev)))html+='<p><a href="https://sdhc.org/wp-content/uploads/2023/05/HCR23-058-8th-Avenue.pdf" target="_blank" rel="noopener">Open SDHC HCR23-058 · printed page 4</a></p>';return html+'<p><a href="./downloads/master-housing-ledger.xlsx">Download the dated source workbook snapshot</a> · <button class="btn" data-source-search="'+esc(r.Project_Name||r.Sender_Project_Name||r.Project_Address)+'">Search preserved City records</button></p></details>'}
const baseRelationship=relationship;
relationship=function(r){if(!r)return baseRelationship(r);let html=baseRelationship(r).replace(/<b>\?<\/b>/,'<b>Unknown</b>');return html+'<div class="callout"><b>'+esc(spatial(r))+'</b><p>'+esc(areaFor(r,'Sender'))+' → '+esc(areaFor(r,'Receiver'))+'</p>'+(r.Relationship_ID==='P2B-T-006'?'<p>Ladera’s missing value is the number of transferred restricted units. The DS-450 describes amenity points; those points are not a unit count.</p>':'')+'</div>'+sourceDetails(r)};
