function geography(){view.innerHTML='<div class="card"><h2>Where obligations move</h2><p>Roads, community areas and straight-line distances. Click a building to see every associated ledger relationship, or select any of the nine records below.</p><div class="selectrow">'+picker()+'<label>Community area <select id="area"><option value="">All mapped locations</option>'+(communityData?.features||[]).sort((a,b)=>a.properties.name.localeCompare(b.properties.name)).map(f=>'<option>'+esc(f.properties.name)+'</option>').join('')+'</select></label><label>Evidence state <select id="mapstate"><option value="">All evidence states</option>'+Object.keys(COLORS).map(s=>'<option>'+s+'</option>').join('')+'</select></label></div><div id="map"></div><div class="map-key maplegend"><b>Map legend</b> <span>■ Sending project</span> <span>● Receiving site</span>'+Object.keys(COLORS).map(stateBadge).join('')+'<span>Solid: verified · dashed: conflicting · dotted: candidate / research identification · gray: unresolved</span></div><p class="small">Scale changes with zoom. Lines indicate relationships, not routes or unit volume. Boundaries: City of San Diego planning areas, retrieved October 26, 2026. Missing-location repairs use exact SanGIS/SANDAG address points retrieved November 3, 2026. The Twain line uses the 4354 address in the source; the 4360 alias remains unresolved. Refuge links identify research-selected senders, not instrument-confirmed allocations. Its 41 units are a group total; individual splits are unknown. Apollo and Flora + Fauna use exact SanGIS/SANDAG address points retrieved November 11, 2026; Rowyn uses the preserved composite-locator match (score 96.15). Missing coordinates are never plotted at zero.</p></div><div class="grid2"><div class="card"><h3>All nine relationships</h3><div id="geo-list"></div></div><div class="card" id="building-detail"><h3>Inspect a building</h3><p>Select a square or circle on the map. Each building opens all related records, including disputed allocations.</p></div></div><div class="card" id="geo-detail"></div>';drawMap();document.getElementById('relpick').onchange=e=>geoSelect(e.target.value,true);document.getElementById('mapstate').onchange=()=>drawMap();document.getElementById('area').onchange=e=>{let f=communityData.features.find(f=>f.properties.name===e.target.value);if(f)map.fitBounds(L.geoJSON(f).getBounds());else drawMap()};geoSelect(focus)}
function buildingPanel(b){let ps=(evidenceData.project_register||[]).filter(p=>b.ids.has(p.Project_ID));document.getElementById('building-detail').innerHTML='<h3>'+esc(b.name)+'</h3><p>'+esc(b.address)+' · '+b.records.length+' related records</p>'+b.records.map(r=>'<button class="record-button" data-geo="'+esc(r.Relationship_ID)+'">'+stateBadge(r.Evidence_Status)+' '+esc(r.Sender_Project_Name||'Unresolved origins')+' → '+esc(r.Receiver_Project_Name)+' · '+unitLabel(r)+'</button>').join('')+ps.map(p=>'<details><summary>Building register · '+esc(p.Project_ID)+'</summary>'+fields(p)+'</details>').join('');}
function drawMap(){if(map){map.stop();map.remove();map=null}geoLayers=[];geoMarkers=[];if(typeof L==='undefined'){document.getElementById('map').innerHTML='<p>Street map could not load. Relationship records and distances remain available below.</p>';renderGeoList();return}map=L.map('map',{scrollWheelZoom:true,zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false}).setView([32.76,-117.15],12);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);L.control.scale({metric:true,imperial:true,maxWidth:160}).addTo(map);if(communityData){const layer=L.geoJSON(communityData,{style:{color:'#496e62',weight:1,fillOpacity:.015},onEachFeature:(f,l)=>l.bindTooltip(esc(f.properties.name),{sticky:true})});layer.addTo(map);L.control.layers(null,{'Community boundaries':layer},{collapsed:true}).addTo(map);for(const f of communityData.features){const p=f.properties;if(/^(UPTOWN|DOWNTOWN|GREATER GOLDEN HILL|GOLDEN HILL|MISSION VALLEY|NORTH PARK|NAVAJO|CLAIREMONT MESA)$/.test(p.name)&&p.label)L.marker([p.label[1],p.label[0]],{interactive:false,icon:L.divIcon({className:'area-label',html:esc(p.name),iconSize:[140,20]})}).addTo(map)}}let selected=document.getElementById('mapstate').value,buildings=new Map(),bounds=[];for(const r of mappedRelationships().filter(r=>!selected||r.Evidence_Status===selected)){for(const role of ['Sender','Receiver']){const p=coord(r,role);if(!p)continue;const key=r[role+'_Project_ID']||r[role+'_Address'];if(!buildings.has(key))buildings.set(key,{p,name:r[role+'_Project_Name']||r[role+'_Address'],address:r[role+'_Address'],roles:new Set(),ids:new Set(),records:[]});const b=buildings.get(key);b.roles.add(role);b.ids.add(r[role+'_Project_ID']);b.records.push(r);bounds.push(p)}const a=coord(r,'Sender'),b=coord(r,'Receiver');if(a&&b){const line=L.polyline([a,b],{color:COLORS[r.Evidence_Status],weight:3,opacity:.8,dashArray:r.Evidence_Status==='Verified'?null:r.Evidence_Status==='Conflicting'?'9 6':'2 7'}).addTo(map).bindTooltip(esc((r.Sender_Project_Name||'Unknown')+' → '+r.Receiver_Project_Name+' · '+r.Evidence_Status+' · '+spatial(r))).on('click',()=>geoSelect(r.Relationship_ID));geoLayers.push({line,row:r})}}for(const b of buildings.values()){const states=[...new Set(b.records.map(r=>r.Evidence_Status))],col=states.length===1?COLORS[states[0]]:'#78bcb1';const receiver=b.roles.has('Receiver');const marker=L.marker(b.p,{title:b.name,keyboard:true,icon:L.divIcon({className:'building-marker',iconSize:[26,26],iconAnchor:[13,13],html:'<span class="building-symbol '+(receiver?'round':'square')+'" style="background:'+col+'">'+b.records.length+'</span>'})}).addTo(map).bindTooltip(esc(b.name+' · '+b.records.length+' records')).on('click',()=>buildingPanel(b));geoMarkers.push(marker)}if(bounds.length)map.fitBounds(bounds,{padding:[35,35],maxZoom:14,animate:false});renderGeoList();let bp=document.getElementById('building-pick');if(bp)bp.remove();bp=document.createElement('label');bp.id='building-pick';bp.innerHTML='Select a building <select aria-label="Select a building"><option value="">Choose a location…</option>'+[...buildings.entries()].map(([key,b])=>'<option value="'+esc(key)+'">'+esc(b.name)+' · '+b.records.length+' records</option>').join('')+'</select>';document.getElementById('map').before(bp);bp.querySelector('select').onchange=e=>{const b=buildings.get(e.target.value);if(b){map.setView(b.p,16,{animate:false});buildingPanel(b)}};geoSelect(focus)}
function renderGeoList(){document.getElementById('geo-list').innerHTML=transfers().map(r=>'<button class="record-button" data-geo="'+esc(r.Relationship_ID)+'">'+stateBadge(r.Evidence_Status)+' <b>'+esc(r.Sender_Project_Name||'Unresolved origins')+' → '+esc(r.Receiver_Project_Name)+'</b><br>'+unitLabel(r)+' · '+esc(spatial(r))+'<br><small>'+esc(areaFor(r,'Sender'))+' → '+esc(areaFor(r,'Receiver'))+'</small></button>').join('')}
function feeClaim(f){if(f.Fee_Record_ID==='FEE-ACCOUNT-2024')return 'Reported aggregate receipts';if(/will (?:be )?pa|will pay/i.test(f.Notes))return 'Planned payment';if(/paying/i.test(f.Notes))return 'Explicit paying language';if(/or pay|or fee|before|prior|option/i.test(f.Notes+' '+f.Fee_Evidence_Status))return 'Fee option / condition';return 'Fee mentioned'}
function feesView(){const f=evidenceData.fee_evidence||[];view.innerHTML='<div class="hero-grid"><div class="card story"><h2>Follow the fee evidence</h2><p>Named City records explicitly describe fee payments, planned payments and fee alternatives. These claims now appear separately. A recorded condition or “paying” note is not a payment receipt.</p><p>The evidence state describes the research record; the source wording below tells you precisely what is documented.</p></div><div class="card"><h2>$14.27m</h2><b>Verified aggregate · 2024 reported receipts</b><p>$14,268,246 from 15 unnamed developments. This aggregate cannot be traced to individual projects or receiving developments.</p>'+stateBadge('Verified')+'</div></div><div class="grid2"><div class="card"><h3>What fee sources document</h3>'+bars(f.reduce((a,r)=>(a[feeClaim(r)]=(a[feeClaim(r)]||0)+1,a),{}))+'</div><div class="card"><h3>Origin program context</h3>'+bars(counts('Source_Program_Label',f))+'<p>Program labels are preserved from each source. Fee evidence is not itself a housing program.</p></div></div><div class="card"><h3>Fee addresses and source language</h3><p>Payer geography is shown by address. Receiving locations, project-level amounts and payment dates remain unknown unless the source supplies them. Address links open a street-map search, not a verified geocode.</p><label>Filter source claim <select id="fee-claim"><option value="">All claims</option>'+[...new Set(f.map(feeClaim))].map(s=>'<option>'+esc(s)+'</option>').join('')+'</select></label><div id="fee-records"></div></div>';const draw=()=>{document.getElementById('fee-records').innerHTML=f.filter(r=>!document.getElementById('fee-claim').value||feeClaim(r)===document.getElementById('fee-claim').value).map(r=>'<article class="fee-record"><h4>'+esc(r.Project_Name||r.Address)+'</h4>'+stateBadge(r.Evidence_Status)+' <b>'+esc(feeClaim(r))+'</b><p>'+esc(r.Source_Program_Label)+' · '+esc(r.Address)+'</p><blockquote>'+esc(r.Notes||'Source wording unknown')+'</blockquote><p>Source: '+esc(r.Source_Record)+' · Amount: '+(r.Fee_Amount!=null?'$'+Number(r.Fee_Amount).toLocaleString():'Unknown')+'</p>'+(r.Fee_Record_ID!=='FEE-ACCOUNT-2024'?'<a target="_blank" rel="noopener" href="https://www.openstreetmap.org/search?query='+encodeURIComponent(r.Address+', San Diego, CA')+'">Find this address on a street map ↗</a>':'')+'<details><summary>Inspect exact fee record · '+esc(r.Fee_Record_ID)+'</summary>'+fields(r)+'</details></article>').join('')};draw();document.getElementById('fee-claim').onchange=draw}
function evidence(){view.innerHTML='<div class="card"><h2>Inspect the evidence behind a conclusion</h2><p>Search preserved City Planning rows by project, address, APN or source wording. These rows record program classifications and notes; conclusions and conflicts remain visible separately in each relationship.</p><label>Search source records <input id="source-query" placeholder="Park Summit, paying, address or APN"></label><div id="source-results"></div></div><div class="card"><h3>Research source register</h3>'+(evidenceData.source_register||[]).map(r=>'<details><summary>'+esc(r.Source_ID+' · '+r.Category)+'</summary>'+fields(r)+'</details>').join('')+'</div>';let draw=()=>{let q=document.getElementById('source-query').value.toLowerCase().trim();let list=q?(evidenceData.cpra_evidence||[]).filter(r=>Object.values(r).join(' ').toLowerCase().includes(q)):[];document.getElementById('source-results').innerHTML='<p>'+list.length+' matching source rows'+(list.length>60?' · first 60 shown, refine your search':'')+'</p>'+list.slice(0,60).map(r=>'<details><summary>'+esc(r.Evidence_Row_ID+' · '+r['Street Address']+' · '+(r['Project Name']||''))+'</summary>'+fields(r)+'</details>').join('')};document.getElementById('source-query').oninput=draw;draw()}
const baseTable=table;
table=function(src=rows){return baseTable(src).replace(/<tr data-record-id="([^"]+)">/g,(m,id)=>m+'<td><button class="btn" data-inspect="'+id+'">Inspect sources</button></td>').replace('<thead><tr>','<thead><tr><th>Sources</th>')};
document.addEventListener('click',e=>{const g=e.target.closest('[data-geo]'),i=e.target.closest('[data-inspect]'),s=e.target.closest('[data-source-search]');if(g)geoSelect(g.dataset.geo,true);if(i){const r=rows.find(r=>r.Relationship_ID===i.dataset.inspect);let d=document.getElementById('record-dialog');if(!d){d=document.createElement('dialog');d.id='record-dialog';document.body.append(d)}d.innerHTML='<button class="btn" id="close-record">Close</button><h2>'+esc(r.Project_Name||r.Relationship_ID)+'</h2>'+sourceDetails(r)+fields(r);d.querySelector('details').open=true;d.querySelector('#close-record').onclick=()=>d.close();d.showModal()}if(s){document.getElementById('record-dialog')?.close();tab='evidence';render();const q=document.getElementById('source-query');q.value=s.dataset.sourceSearch;q.dispatchEvent(new Event('input'))}});

let locationMatches={};
function matchFor(r,role){let key=role==='Receiver'&&['P2B-T-002','P2B-T-003'].includes(r.Relationship_ID)?'receiver-1267':role==='Sender'&&r.Relationship_ID==='P2B-T-009'?'sender-friars':role==='Sender'&&r.Relationship_ID==='P2B-T-004'?'sender-twain-4354':null;return locationMatches[key]}
const ledgerCoord=coord;
coord=function(r,role){return matchFor(r,role)?.point||ledgerCoord(r,role)};
function areaFor(r,role){return matchFor(r,role)?.community||r[role+'_Community_Plan_Area']||'Unknown'}
spatial=function(r){const a=coord(r,'Sender'),b=coord(r,'Receiver');if(!a||!b)return 'Distance unknown — '+(!a?'sender':'receiver')+' coordinates missing.';return miles(a,b).toFixed(2)+' miles straight-line (not a travel route)'+(r.Relationship_ID==='P2B-T-004'?' · uses 4354 Twain source address; 4360 alias unresolved':'')};
const priorRelationship=relationship;
relationship=function(r){let text=priorRelationship(r);if(!r)return text;const from=areaFor(r,'Sender'),to=areaFor(r,'Receiver'),different=from.toUpperCase()!==to.toUpperCase();text+='<p class="callout"><b>Community comparison: '+esc(from)+' → '+esc(to)+'</b><br>'+(from==='Unknown'||to==='Unknown'?'Cross-community status unknown.':different?'Different named community areas; review location provenance below.':'Same named community area.')+'</p>';for(const role of ['Sender','Receiver']){const m=matchFor(r,role);if(m)text+='<details><summary>'+role+' location source · SanGIS/SANDAG address point</summary>'+fields(m)+'<a href="'+esc(m.source)+'" target="_blank" rel="noopener">Open the exact public GIS feature</a></details>'}return text};
const baseFeesView=feesView;
feesView=function(){baseFeesView();const c=document.createElement('div');c.className='card';c.innerHTML='<h3>Geography of fee-source addresses</h3><p>Diamonds locate addresses mentioned in fee evidence. They do not establish payment or a receiving development. Click a diamond for the program, exact source wording and GIS provenance.</p><div id="fee-map"></div><div class="map-key">◆ Fee-source address '+Object.keys(COLORS).map(stateBadge).join('')+'</div><p id="fee-map-count" class="small"></p>';document.getElementById('fee-records').parentNode.before(c);if(typeof L==='undefined')return;map=L.map('fee-map',{scrollWheelZoom:true,zoomAnimation:false,fadeAnimation:false,markerZoomAnimation:false}).setView([32.74,-117.14],11);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);L.control.scale({metric:true,imperial:true}).addTo(map);const pts=[];let matched=0;for(const f of evidenceData.fee_evidence){const m=locationMatches[f.Fee_Record_ID];if(!m)continue;matched++;for(const point of [m,locationMatches[f.Fee_Record_ID+'b']].filter(Boolean)){pts.push(point.point);L.marker(point.point,{title:f.Address,icon:L.divIcon({className:'building-marker',iconSize:[24,24],html:'<span class="fee-symbol" style="background:'+COLORS[f.Evidence_Status]+'"></span>'})}).addTo(map).bindPopup('<b>'+esc(f.Project_Name||f.Address)+'</b><p>'+esc(point.community)+' · '+esc(f.Source_Program_Label)+'</p>'+stateBadge(f.Evidence_Status)+'<p><b>'+esc(feeClaim(f))+'</b></p><blockquote>'+esc(f.Notes)+'</blockquote><p>'+esc(f.Source_Record)+'</p><p>GIS address match; not proof of project identity or payment. '+esc(point.method)+'</p><a href="'+esc(point.source)+'" target="_blank" rel="noopener">Inspect public GIS source</a>')}}if(pts.length)map.fitBounds(pts,{padding:[30,30]});document.getElementById('fee-map-count').textContent=matched+' of 19 named fee-evidence records have exact address-point matches ('+pts.length+' address locations). '+(19-matched)+' remain unlocated; the aggregate account has no payer addresses. No fee-to-receiver connections are invented.';const feeDraw=document.getElementById('fee-claim').onchange;document.getElementById('fee-claim').onchange=()=>{feeDraw();document.getElementById('fee-map-count').textContent=matched+' of 19 named records mapped. Claim filter applies to the source list below; map retains all matched fee addresses.'}}

function overview(){
 const ts=transfers(),states=Object.keys(COLORS),ver=ts.filter(r=>r.Evidence_Status==='Verified');
 ledger(); // Keep the complete, searchable ledger and its existing controls on the overview.
 const ledgerCard=view.firstElementChild;ledgerCard.classList.add('overview-ledger');
 const receiverCounts={};for(const r of ts){if(!r.Sender_Project_Name||!r.Receiver_Project_Name)continue;const raw=r.Units_Transferred||r.Units_Recorded;if(raw===''||raw==null)continue;let k=r.Receiver_Project_Name;if(!receiverCounts[k])receiverCounts[k]={};receiverCounts[k][r.Evidence_Status]=(receiverCounts[k][r.Evidence_Status]||0)+Number(raw)}
 const max=Math.max(...Object.values(receiverCounts).map(v=>Object.values(v).reduce((a,b)=>a+b,0)),1);
 const allocations=Object.entries(receiverCounts).map(([name,v])=>'<div class="allocation-row"><b>'+esc(name)+'</b><div class="allocation-track">'+states.filter(s=>v[s]).map(s=>'<span style="width:'+(v[s]/max*100)+'%;background:'+COLORS[s]+'" title="'+s+' · '+v[s]+' listed units">'+v[s]+'</span>').join('')+'</div></div>').join('');
 const count=counts('Evidence_Status',ts);let offset=0;const stops=states.map(s=>{let start=offset;offset+=(count[s]||0)/ts.length*100;return COLORS[s]+' '+start+'% '+offset+'%'}).join(',');
 view.insertAdjacentHTML('afterbegin','<div class="overview-intro"><div><h2>Uncovering the transparency gap in San Diego’s affordable housing policy</h2><p>Trace where affordable housing obligations originate, how they are met, and where the public record breaks down.</p></div><button class="btn" data-overview-tab="geography">Explore the geography ↗</button></div><div class="overview-kpis">'+[[rows.length,'Pathway records'],[ts.length,'Transfer relationships'],[ver.length,'Verified transfer records'],[ver.reduce((a,r)=>a+Number(r.Units_Transferred||r.Units_Recorded||0),0),'Listed units in verified records'],['$14.27m','2024 aggregate fee receipts']].map(([v,l])=>'<div><strong>'+v+'</strong><span>'+l+'</span></div>').join('')+'</div><p class="metric-note">Listed units are ledger counts, not deduplicated delivery totals. Fee receipts are an aggregate and cannot be traced to individual projects.</p><div class="overview-layout"><aside class="overview-left"><section class="card"><h3>Relationship evidence</h3><div class="evidence-ring" style="background:conic-gradient('+stops+')"><div><b>'+ver.length+' of '+ts.length+'</b><small>verified</small></div></div>'+states.map(s=>'<div class="state-count">'+stateBadge(s)+'<b>'+(count[s]||0)+'</b></div>').join('')+'</section><section class="card"><h3>Compliance pathways</h3>'+bars({'Off-site / receiving records':ts.length,'On-site records':rows.filter(r=>r.Record_Type==='On-site obligation').length,'Fee evidence records':fees().length})+'<p class="small">Counts describe research records, not distinct developments or confirmed payments.</p></section><section class="card"><h3>What this shows</h3><p>Several origins can converge on one receiving site.</p><p>Verified allocations and disputed claims remain distinct.</p><p>Aggregate receipts do not identify each payer or funded project.</p></section></aside><section class="card overview-flow"><h2>Follow the obligation</h2><p>Origin project → listed units → receiving project. Select a connection to inspect the evidence.</p><div class="flow-legend">'+states.map(stateBadge).join('')+'</div><div class="flow-scroll"><div class="flow-records">'+ts.map(r=>'<button class="flow-row" data-flow-id="'+esc(r.Relationship_ID)+'" style="--evidence:'+COLORS[r.Evidence_Status]+'"><span class="flow-origin"><b>'+esc(r.Sender_Project_Name||'Unresolved origins')+'</b><small>'+esc(r.Sender_Address||'Sending addresses unknown')+'</small></span><span class="flow-link '+(r.Evidence_Status==='Verified'?'solid':'dashed')+'"><b>'+unitLabel(r)+'</b><span>→</span></span><span class="flow-receiver"><b>'+esc(r.Receiver_Project_Name||'Unknown receiver')+'</b><small>'+esc(r.Evidence_Status)+'</small></span>'+(r.Relationship_ID==='P2B-T-007'?'<small class="flow-reason">Disputed: City off-site coding conflicts with the recorded program and governing dates.</small>':r.Relationship_ID==='P2B-T-008'?'<small class="flow-reason">Disputed: project and receiving-site unit counts differ across sources; retain the 35-unit claim separately.</small>':r.Relationship_ID==='P2B-T-006'?'<small class="flow-reason">Missing: transferred unit count. Amenity points do not establish housing units.</small>':'')+'</button>').join('')+'</div></div><p class="small">Columbia Square and Digital-Columbia may be aliases; their ledger rows are shown separately without asserting separate delivery.</p></section><aside class="card overview-detail"><h3>Selected relationship</h3><div id="overview-selection"></div></aside></div><div class="overview-bottom"><section class="card"><h3>Where recorded obligations land</h3><p>Allocations with identified origins and known listed-unit counts. Evidence states remain separate.</p>'+allocations+'<p class="small">The Refuge has three research-identified sending locations; its 41-unit aggregate is separate from any unknown individual split.</p></section><section class="card"><h3>Evidence chain</h3><p>Each conclusion can be checked against the preserved research record.</p>'+['Origin identified','Receiver identified','Listed-unit count recorded','Source documented','Confidence assigned'].map(s=>'<div class="chain-row"><span>'+s+'</span><span>Inspect per record ↗</span></div>').join('')+'<button class="btn" data-overview-tab="evidence">Explore the source records</button></section></div>');
 function choose(id){let r=ts.find(r=>r.Relationship_ID===id)||ts[0];focus=r.Relationship_ID;document.querySelectorAll('[data-flow-id]').forEach(b=>b.classList.toggle('selected',b.dataset.flowId===focus));document.getElementById('overview-selection').innerHTML=stateBadge(r.Evidence_Status)+'<h3>'+esc(r.Sender_Project_Name||'Unresolved origins')+' → '+esc(r.Receiver_Project_Name)+'</h3><strong>'+unitLabel(r)+'</strong><p>'+esc(r.Origin_Program||r.Program)+'</p><p>'+esc(r.Evidence_Summary)+'</p><p>'+esc(spatial(r))+'</p>'+sourceDetails(r)+'<button class="btn" data-overview-tab="relationships">Open full relationship</button>'}
 document.querySelectorAll('[data-flow-id]').forEach(b=>b.onclick=()=>choose(b.dataset.flowId));choose(focus);
}
document.addEventListener('click',e=>{let b=e.target.closest('[data-overview-tab]');if(b){tab=b.dataset.overviewTab;render();window.scrollTo({top:0,behavior:'smooth'})}});


/* Evidence-first overview restoration. Original ledger and drilldowns remain authoritative. */
function programName(r){
  const label=(r.Origin_Program||r.Program_Source_Label||r.Program||'Not established').trim();
  if(/complete communities/i.test(label))return 'Complete Communities';
  if(/density bonus/i.test(label))return 'Affordable Housing Density Bonus';
  if(/inclusionary/i.test(label)&&!/adu/i.test(label))return 'Inclusionary Housing';
  if(/adu/i.test(label))return 'ADU Bonus / Inclusionary';
  return label==='Program not established'||label==='Other'?'Program not established':label;
}
function pathwayName(r){if(r.Record_Type==='Aggregate in-lieu account')return 'Aggregate fee account';if(r.Compliance_Pathway==='In-lieu fee')return 'Fee evidence';if(r.Record_Type==='On-site obligation')return 'On-site';if(r.Record_Type==='Transfer relationship')return r.Sender_Project_Name?'Off-site / transfer':'Receiving site · origins unknown';return 'Other'}
function groupRecords(list,key){return list.reduce((a,r)=>(a[key(r)]=(a[key(r)]||0)+1,a),{})}
function linkTab(target){tab=target;render();window.scrollTo({top:0,behavior:'instant'})}
function originalAreaFromRecord(r,role){return matchFor(r,role)?.community||r[role+'_Community_Plan_Area']}
function insideRing(point,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){let x=ring[i][0],y=ring[i][1],xx=ring[j][0],yy=ring[j][1];if(((y>point[1])!==(yy>point[1]))&&(point[0]<(xx-x)*(point[1]-y)/(yy-y)+x))inside=!inside}return inside}
function insidePolygon(point,polygon){return polygon.length>0&&insideRing(point,polygon[0])&&!polygon.slice(1).some(hole=>insideRing(point,hole))}
function computedArea(r,role){let p=coord(r,role);if(!p||!communityData?.features)return '';let xy=[p[1],p[0]];for(const f of communityData.features){let g=f.geometry;if(!g)continue;let polys=g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[];if(polys.some(polygon=>insidePolygon(xy,polygon)))return f.properties?.name||''}return ''}
areaFor=function(r,role){const name=originalAreaFromRecord(r,role)||computedArea(r,role);return name||'Not geographically resolved'};
function overviewSelect(id){focus=id;let r=transfers().find(r=>r.Relationship_ID===id);if(!r)return;const detail=document.getElementById('overview-rel-detail');if(detail)detail.innerHTML=relationship(r);const picker=document.getElementById('relpick');if(picker)picker.value=id;const label=document.getElementById('overview-selection');if(label)label.textContent='Selected: '+id;document.querySelectorAll('[data-flow-id]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.flowId===id)))}
function evidenceProgramMatrix(records){
  let groups=Object.entries(groupRecords(records,programName)).sort((a,b)=>b[1]-a[1]);
  const stages=['On-site','Off-site / transfer','Receiving site · origins unknown','Fee evidence','Aggregate fee account'];
  const cls=['mint','teal','slate','terracotta','slate'];
  return '<div class="program-matrix" role="group" aria-label="Program and compliance pathway comparison">'+groups.map(([name,count])=>{let recs=records.filter(r=>programName(r)===name),bands=stages.map(st=>recs.filter(r=>pathwayName(r)===st).length);
  return '<button class="matrix-row" type="button" data-program="'+esc(name)+'" aria-label="Explore '+esc(name)+'"><span class="matrix-name">'+esc(name)+'</span><span class="matrix-track">'+bands.map((v,i)=>v?'<span class="matrix-segment '+cls[i]+'" style="flex:'+v+'" title="'+esc(stages[i])+': '+v+'"></span>':'').join('')+'</span><b>'+count+'</b></button>'}).join('')+'</div><div class="legend"><span><i class="dot" style="background:var(--mint)"></i>On-site</span><span><i class="dot" style="background:var(--teal)"></i>Off-site</span><span><i class="dot" style="background:var(--slate)"></i>Receiving origin unknown / aggregate</span><span><i class="dot" style="background:var(--coral)"></i>Fee evidence</span></div>'}
function compactEvidenceGrid(){return '<div class="evidence-stack">'+['Verified','Conflicting','Candidate','Unresolved'].map(status=>[status,rows.filter(r=>r.Evidence_Status===status).length]).filter(([,count])=>count>0).map(([status,count])=>'<button type="button" class="evidence-tile" data-evidence="'+status+'"><span class="evidence-count">'+count+'</span>'+stateBadge(status)+'</button>').join('')+'</div>'}
function placesPanel(){const ts=mappedRelationships(),entries={};for(const r of ts){for(const role of ['Sender','Receiver']){if(!coord(r,role))continue;let name=areaFor(r,role);if(name==='Not geographically resolved')continue;let e=entries[name]||(entries[name]={senders:new Set(),receivers:new Set()});e[role==='Sender'?'senders':'receivers'].add(role==='Sender'?(r.Sender_Project_ID||r.Sender_Address||r.Relationship_ID):(r.Receiver_Project_ID||r.Receiver_Address||r.Relationship_ID))}}let sorted=Object.entries(entries).sort((a,b)=>(b[1].senders.size+b[1].receivers.size)-(a[1].senders.size+a[1].receivers.size));return '<div class="places-grid">'+sorted.slice(0,7).map(([name,val])=>'<button class="place-pill" data-place="'+esc(name)+'"><strong>'+esc(name)+'</strong><span>'+val.senders.size+' sending sites · '+val.receivers.size+' receiving sites</span></button>').join('')+'</div><p class="small">Geographic grouping uses known project coordinates and City community planning areas, not permit totals. Unlocated records are excluded from these counts.</p>'}
overview=function(){const ts=transfers(),ons=rows.filter(r=>r.Record_Type==='On-site obligation'),fee=fees(),chosen=ts.find(r=>r.Relationship_ID===focus)||ts[0];
const refuse=ts.find(r=>r.Relationship_ID==='P2B-T-005');
const bel=ts.filter(r=>r.Receiver_Project_Name==='The Bel');
view.innerHTML=
'<section class="intro-band"><div><span class="eyebrow">THE GEOGRAPHY OF HOUSING COMPLIANCE</span><h2>Uncovering the transparency gap in San Diego’s affordable housing policy</h2><p>What does the public receive in exchange for the incentives granted to developers? This dashboard follows affordable housing obligations, off-site transfers, and fee records to examine how much affordability is secured, where it is located, and whether the evidence supports the promises made.</p></div><button class="btn intro-link" data-jump="relationships">Explore the relationships ↗</button></section>'+
'<div class="metrics-strip"><div><b>'+rows.length+'</b><span>evidence records</span></div><div><b>'+ts.length+'</b><span>transfer / receiving relationships</span></div><div><b>'+ons.length+'</b><span>on-site comparisons</span></div><div><b>'+fee.length+'</b><span>fee-source & account records</span></div></div>'+
'<div class="grid2 overview-main"><section class="card"><div class="section-title"><div><h3>How obligations are recorded</h3><p>Program × compliance pathway · count of ledger records, not housing units</p></div></div>'+evidenceProgramMatrix(rows)+'</section><section class="card"><div class="section-title"><div><h3>How much can the records prove?</h3><p>Evidence status determines how each connection is interpreted.</p></div></div>'+compactEvidenceGrid()+'<p class="small">Evidence status reflects the strength of the compliance relationship—not whether a completed building is occupied. Select a state to inspect its source records.</p><div class="pathway-note"><b>Reading the evidence</b><p>Origin → compliance pathway → receiving site → recorded restriction. Occupancy is intentionally excluded from compliance classification.</p></div></section></div>'+
'<section class="card overview-trace"><div class="section-title"><div><h2>Follow a sending project to its receiving site</h2><p>Select a relationship to see location, units, program, confidence and source evidence.</p></div><button class="btn" data-jump="geography">Show on map ↗</button></div><div class="overview-relationship-layout"><div class="overview-flow-list">'+ts.map(r=>'<button type="button" data-flow-id="'+esc(r.Relationship_ID)+'" aria-pressed="'+(r.Relationship_ID===chosen.Relationship_ID)+'"><span><strong>'+esc(r.Sender_Project_Name||'Unidentified sending projects')+'</strong><small>'+esc(r.Relationship_ID)+' · '+esc(r.Receiver_Project_Name||r.Receiver_Address||'Destination unresolved')+'</small></span>'+stateBadge(r.Evidence_Status)+'</button>').join('')+'</div><div id="overview-rel-detail">'+relationship(chosen)+'</div></div></section>'+
'<div class="grid2 case-study-grid"><section class="card case-study-card"><div class="section-title visual-heading"><div><span class="eyebrow">CASE STUDY 01</span><h3>The Bel: a disclosed transfer trail</h3><p>Named market-rate origins, one affordable receiver, and an SDHC allocation record.</p></div></div><div class="case-study-flow"><div><b>Park Summit</b><span>555 Upas · Uptown</span><strong>24 units</strong></div><i>→</i><div class="case-receiver"><b>The Bel</b><span>3927 Eighth · Uptown</span></div></div><div class="case-study-flow"><div><b>The Lindley</b><span>445 W. Ash / 1331 Columbia · Downtown / Little Italy edge</span><strong>35 units</strong></div><i>→</i><div class="case-receiver"><b>The Bel</b><span>59 Density Bonus units from the two named senders</span></div></div><p class="case-finding">The transfer relationships are confirmed. Other source discrepancies are retained separately and do not downgrade the sender→receiver links.</p><button class="btn" data-case-id="P2B-T-001">Park Summit ↗</button><button class="btn" data-case-id="P2B-T-008">The Lindley ↗</button></section><section class="card case-study-card refuge-case"><div class="section-title visual-heading"><div><span class="eyebrow">CASE STUDY 02</span><h3>The Refuge / Amani: reconstructing the origins ourselves</h3><p>The public record disclosed 41 units and general sender geographies—not an easily traceable three-project sender table.</p></div></div><div class="refuge-origin-grid"><div><b>Apollo</b><span>2903 Fourth · Bankers Hill</span></div><div><b>Flora + Fauna</b><span>411 Ivy / 2191 Fourth · Bankers Hill</span></div><div><b>Rowyn</b><span>3775 Sixth · Hillcrest</span></div></div><div class="case-arrow">↓ <b>41 units combined</b> ↓</div><div class="refuge-receiver"><b>The Refuge / Amani</b><span>3725 30th Street · Greater North Park</span></div><p class="case-finding">These origins were research-identified through cross-referencing geography, program context, timing, project records and competing candidates. Individual unit allocations remain to be documented.</p><button class="btn" data-case-id="P2B-T-005">Inspect evidence ↗</button></section></div>'+'<div class="overview-bottom"><span>The ledger is the controlling record. Fee evidence, recorded obligations, on-site compliance and off-site allocations are kept as distinct measures.</span><button class="btn" data-jump="ledger">Inspect all 34 records ↗</button></div><details class="overview-ledger"><summary>Open the full evidence ledger · '+rows.length+' records</summary>'+table(rows)+'</details>';
};
const previousPrograms=programsView;
