const previousHome=overview;
const HOME_COLORS={gold:'#b4935f',blue:'#77a9d9',teal:'#65c9bd',lavender:'#ad9bc9',fuchsia:'#ef65c5',orange:'#ecaa76',gray:'#aab7c5'};
function homeHeading(tab,title,caption){return '<div class="section-title"><div><span class="eyebrow">'+esc(tab==='ledger'?'Master ledger':(TABS.find(t=>t[0]===tab)?.[1]||tab))+'</span><h3>'+title+'</h3><p>'+caption+'</p></div><button class="btn" data-jump="'+tab+'">Explore ↗</button></div>'}
function homeDonut(){const groups=[['Transfer / receiving',transfers().length,HOME_COLORS.fuchsia],['On-site',rows.filter(r=>r.Record_Type==='On-site obligation').length,HOME_COLORS.teal],['Named fee evidence',fees().filter(r=>r.Record_Type!=='Aggregate in-lieu account').length,HOME_COLORS.blue],['Aggregate fee account',fees().filter(r=>r.Record_Type==='Aggregate in-lieu account').length,HOME_COLORS.lavender]];let cursor=0;const stops=groups.map(([name,n,color])=>{let start=cursor;cursor+=n/rows.length*100;return color+' '+start+'% '+cursor+'%'}).join(',');return '<section class="card home-chart" data-home-visual="donut">'+homeHeading('ledger','Which compliance paths appear in the ledger?','Compare record types; this is a research sample, not the citywide housing supply.')+'<div class="home-donut-layout"><div class="home-donut" role="img" aria-label="'+esc(groups.map(([l,n])=>l+': '+n).join('; '))+'" style="background:conic-gradient('+stops+')"><div><b>'+rows.length+'</b><span>records</span></div></div><div>'+groups.map(([l,n,c])=>'<div class="home-key"><i style="background:'+c+'"></i><span>'+l+'</span><b>'+n+'</b></div>').join('')+'</div></div></section>'}
function homeGeography(){const grouped={};for(const r of mappedRelationships())for(const role of ['Sender','Receiver']){if(!coord(r,role))continue;const area=areaFor(r,role);const g=grouped[area]||(grouped[area]={Sender:new Set(),Receiver:new Set()});g[role].add(r[role+'_Project_ID']||r[role+'_Address'])}const entries=Object.entries(grouped).sort((a,b)=>(b[1].Sender.size+b[1].Receiver.size)-(a[1].Sender.size+a[1].Receiver.size));const max=Math.max(...entries.flatMap(([,v])=>[v.Sender.size,v.Receiver.size]),1);return '<section class="card home-chart" data-home-visual="dumbbell">'+homeHeading('geography','Which areas send—and which receive?','Distinct mapped sites by community planning area. One site can appear in multiple relationships.')+'<div class="home-key"><i style="background:'+HOME_COLORS.gold+'"></i>Sending sites <i style="background:'+HOME_COLORS.blue+'"></i>Receiving sites</div><div class="geo-comparisons">'+entries.map(([name,v])=>{let a=v.Sender.size,b=v.Receiver.size;return '<button class="geo-comparison" data-place="'+esc(name)+'"><span>'+esc(name)+'</span><span class="dumbbell-axis"><i style="left:'+Math.min(a,b)/max*90+'%;width:'+Math.abs(a-b)/max*90+'%"></i><b class="sender-dot" style="left:'+a/max*90+'%" title="'+a+' sending sites">'+a+'</b><b class="receiver-dot" style="left:'+b/max*90+'%" title="'+b+' receiving sites">'+b+'</b></span></button>'}).join('')+'</div><p class="small">Dots share a zero-based scale. Select an area to open the map. Records with unknown locations remain in the ledger.</p></section>'}
function homeFees(){const all=evidenceData.fee_evidence||[],counts={};for(const f of all){const k=feeClaim(f);counts[k]=(counts[k]||0)+1}const colors=[HOME_COLORS.gold,HOME_COLORS.teal,HOME_COLORS.lavender,HOME_COLORS.blue,HOME_COLORS.fuchsia];const max=Math.max(...Object.values(counts),1);return '<section class="card home-chart" data-home-visual="lollipop">'+homeHeading('fees','What do fee records actually establish?','Compare exact source claims, rather than treating every mention as a paid fee.')+'<div class="home-lollipops">'+Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([name,n],i)=>'<div class="home-lollipop"><span>'+esc(name)+'</span><div><i style="width:'+n/max*88+'%;background:'+colors[i%colors.length]+'"></i><b style="left:'+n/max*88+'%;background:'+colors[i%colors.length]+'">'+n+'</b></div></div>').join('')+'</div><p class="fee-aggregate"><strong>$14.27m</strong> verified 2024 aggregate receipts</p><p class="small">$14,268,246 from 15 unnamed developments. Individual payers and downstream projects cannot be traced from this aggregate. “Paying” language and a payment receipt are different evidence claims.</p></section>'}
function homeAllocations(){const group={};for(const r of transfers()){if(!r.Sender_Project_Name)continue;let raw=r.Units_Transferred||r.Units_Recorded;if(raw==null||raw==='')continue;let g=group[r.Receiver_Project_Name]||(group[r.Receiver_Project_Name]={});g[r.Evidence_Status]=(g[r.Evidence_Status]||0)+Number(raw)}const max=Math.max(...Object.values(group).map(v=>Object.values(v).reduce((a,b)=>a+b,0)),1);return '<section class="card home-chart" data-home-visual="stacked-bar">'+homeHeading('relationships','Where do identified allocations land?','Listed units by receiving project and evidence state. Disputed values remain visible separately.')+'<div class="flow-legend">'+Object.keys(COLORS).map(stateBadge).join('')+'</div>'+Object.entries(group).map(([name,v])=>'<div class="home-allocation"><b>'+esc(name)+'</b><div>'+Object.entries(v).map(([s,n])=>'<span style="width:'+n/max*100+'%;background:'+COLORS[s]+'" title="'+esc(s)+' · '+n+' listed units">'+n+'</span>').join('')+'</div></div>').join('')+'<p class="small">The Refuge’s 41 reported inbound units are counted once as a Candidate aggregate for Apollo, Flora + Fauna and Rowyn. The allocation to each sender remains unknown. Columbia Square / Digital-Columbia may be aliases: the two 15-unit rows are not proof of 30 distinct delivered units. Ladera’s missing unit count remains unknown.</p></section>'}
function homeHeatmap(){const types=[...new Set(rows.map(r=>r.Record_Type))],states=Object.keys(COLORS);return '<section class="card home-chart" data-home-visual="heatmap">'+homeHeading('evidence','Where is the evidence strongest—or incomplete?','Compare record type with evidence state. Each cell counts ledger records.')+'<div class="tablewrap home-heatmap"><table><thead><tr><th>Record type</th>'+states.map(s=>'<th>'+stateBadge(s)+'</th>').join('')+'</tr></thead><tbody>'+types.map(t=>'<tr><th>'+esc(t)+'</th>'+states.map(s=>{let n=rows.filter(r=>r.Record_Type===t&&r.Evidence_Status===s).length;return '<td><button data-evidence="'+s+'" style="background:'+COLORS[s]+(n?'3d':'08')+';border-color:'+COLORS[s]+'" aria-label="'+esc(t)+', '+s+': '+n+' records. Open state filter.">'+n+'</button></td>'}).join('')+'</tr>').join('')+'</tbody></table></div><p class="small">Select a cell to inspect that evidence state across the full ledger. Zero means no records in this sample; it does not establish no activity citywide.</p></section>'}
function homeLedger(){return '<section class="card home-chart" data-home-section="ledger">'+homeHeading('ledger','See the records behind the visuals','A preview of the controlling ledger. Open all 34 records for search, evidence filters and downloads.')+'<div class="tablewrap"><table><thead><tr><th>Record</th><th>Origin → receiver</th><th>Listed units</th><th>Evidence</th><th>Sources</th></tr></thead><tbody>'+transfers().slice(0,5).map(r=>'<tr><td>'+esc(r.Relationship_ID)+'</td><td>'+esc(r.Sender_Project_Name||'Unresolved origins')+' → '+esc(r.Receiver_Project_Name)+'</td><td>'+unitLabel(r)+'</td><td>'+stateBadge(r.Evidence_Status)+'</td><td><button class="btn" data-inspect="'+r.Relationship_ID+'">Inspect sources</button></td></tr>').join('')+'</tbody></table></div></section>'}
overview=function(){previousHome();const top=document.querySelector('.overview-main');const charts=document.createElement('div');charts.className='home-comparison-grid';charts.innerHTML=homeDonut()+homeGeography()+homeFees()+homeAllocations()+homeHeatmap();if(top)top.after(charts);else view.append(charts);const footer=view.querySelector('.overview-bottom');if(footer)footer.before(document.createRange().createContextualFragment(homeLedger()));else view.insertAdjacentHTML('beforeend',homeLedger());const matrix=view.querySelector('.program-matrix');if(matrix){matrix.closest('.card').dataset.homeVisual='program-matrix';matrix.insertAdjacentHTML('beforebegin','<span class="eyebrow">Programs</span>')}const trace=view.querySelector('.overview-trace');if(trace)trace.dataset.homeSection='relationships'};



const REFUGE_RESEARCH_SENDERS=[
 {key:'refuge-apollo',name:'Apollo',address:'2903 Fourth Avenue',area:'Bankers Hill',developer:'Hub & Spoke Communities',url:'https://hubspokeco.com/project/apollo/',basis:'Developer identifies an 82-unit Bankers Hill project. CPRA-0335 separately codes six affordable units on-site; this contrary evidence must be reconciled before confirming a Refuge allocation.'},
 {key:'refuge-flora-fauna',name:'Flora + Fauna',address:'411 Ivy Street / 2191 Fourth Avenue',area:'Bankers Hill',developer:'Raintree Partners',url:'https://raintreepartners.com/property/flora-fauna/',basis:'Developer confirms the 411 Ivy Street project. Source totals vary (185/186/189); none establishes a Refuge allocation.'},
 {key:'refuge-rowyn',name:'Rowyn',address:'3775 Sixth Avenue',area:'Hillcrest',developer:'Carmel Partners',url:'https://www.carmelpartners.com/project/rowyn/',basis:'Developer confirms the Hillcrest address and 435-unit project. The individual program and off-site allocation instrument remain to be located.'}
];
/** Expand only map geometry; the controlling ledger retains one 41-unit aggregate. */
function mappedRelationships(){
 return transfers().flatMap(r=>r.Relationship_ID!=='P2B-T-005'?[r]:REFUGE_RESEARCH_SENDERS.map(x=>{
  const m=locationMatches[x.key];return {...r,Sender_Project_ID:x.key,Sender_Project_Name:x.name,Sender_Address:x.address,Sender_APN:m?.attributes?.apn||'',Sender_Latitude:m?.point[0]??'',Sender_Longitude:m?.point[1]??'',Sender_Community_Plan_Area:'Uptown',Research_Sender_Name:x.name,Units_Transferred:'',Units_Recorded:''};
 }));
}
function refugeResearchPanel(){
 return '<div class="callout refuge-research"><b>Research-identified Refuge/Amani senders</b><p>Public reporting establishes 41 transferred units from two Bankers Hill projects and one Hillcrest project, without naming them. The retained research identification is Apollo, Flora + Fauna and Rowyn. City/SDHC allocation instruments and the project-level split remain outstanding.</p>'+REFUGE_RESEARCH_SENDERS.map((x,i)=>'<article data-refuge-sender="'+esc(x.key)+'"><strong>'+(i+1)+'. '+esc(x.name)+'</strong> · '+esc(x.area)+'<br><span>'+esc(x.address)+' · '+esc(x.developer)+'</span><small>'+esc(x.basis)+'</small><p><a href="'+esc(x.url)+'" target="_blank" rel="noopener">Developer project record ↗</a>'+(locationMatches[x.key]?' · <a href="'+esc(locationMatches[x.key].source)+'" target="_blank" rel="noopener">GIS location source ↗</a>':'')+'</p></article>').join('')+'<p class="small"><b>41 units combined; individual allocations unknown.</b> Dotted connections show research identification, not confirmed transfers. The separate 16-unit One Mississippi transaction is not assigned to these senders.</p><p><a href="https://www.kpbs.org/news/living/2025/03/28/north-park-churchs-affordable-housing-project-highlights-new-market-of-off-site-housing-credits" target="_blank" rel="noopener">KPBS · March 28, 2025 · aggregate and neighborhoods ↗</a></p></div>';
}
const individualSpatial=spatial;
spatial=function(r){return r.Relationship_ID==='P2B-T-005'&&!r.Research_Sender_Name?'Three research-identified sending locations; inspect each dotted map connection for its straight-line distance.':individualSpatial(r)};

function relationshipVisual(r){if(!r)return '';if(r.Relationship_ID==='P2B-T-008')return '<div class="building-visual-pair"><a href="https://www.livethelindley.com/" target="_blank" rel="noopener"><img src="https://architizer-prod.imgix.net/media/mediadata/uploads/1752684226899City_1.jpg" alt="The Lindley high-rise in Downtown San Diego"><span>The Lindley · sender</span></a><div class="visual-arrow">35 →</div><a href="https://www.livethebel.com/gallery/" target="_blank" rel="noopener"><img src="https://media.apts247.info/3d/3d3c5202f9584f038469ba90910027a4/galleries/community/community/8th_Ave-The_Bell.jpg" alt="The Bel affordable housing development"><span>The Bel · receiver</span></a></div>';return ''}
/* Canonical display cleanup: preserve source text, normalize geography and entity presentation. */
function canonicalAreaName(value){
  let raw=String(value||'').trim();if(!raw)return '';
  let key=raw.toUpperCase().replace(/\s+/g,' ').trim();
  const aliases={
    'DOWNTOWN':'Downtown','UPTOWN':'Uptown','NAVAJO':'Navajo','MISSION VALLEY':'Mission Valley',
    'GREATER NORTH PARK':'Greater North Park','GREATER GOLDEN HILL':'Greater Golden Hill','LINDA VISTA':'Linda Vista',
    'SCRIPPS MIRAMAR RANCH':'Scripps Miramar Ranch','COLLEGE AREA':'College Area','PENINSULA':'Peninsula',
    'OTAY MESA-NESTOR':'Otay Mesa-Nestor','SKYLINE-PARADISE HILLS':'Skyline-Paradise Hills',
    'MID-CITY:CITY HEIGHTS':'Mid-City: City Heights','SOUTHEASTERN SAN DIEGO,SOUTHEASTERN':'Southeastern San Diego',
    'SOUTHEASTERN SAN DIEGO':'Southeastern San Diego','SAN DIEGO':'San Diego'
  };
  return aliases[key]||raw.toLowerCase().replace(/(^|[\s:/-])([a-z])/g,(m,p,c)=>p+c.toUpperCase());
}
function displayProjectName(r,role){
  let v=role==='Sender'?(r.Sender_Project_Name||r.Project_Name):(r.Receiver_Project_Name||r.Receiver_Address);
  if(v)return String(v).trim().replace(/\. Sends to .*/i,'').replace(/ on the extract row$/i,'');
  if(role==='Sender'&&r.Relationship_ID==='P2B-T-005')return 'Apollo + Flora + Fauna + Rowyn';
  return role==='Sender'?'Project name not established':'Receiving project name not established';
}
function displayAddress(r,role){
  let v=role==='Sender'?(r.Sender_Address||r.Project_Address):r.Receiver_Address;
  if(v)return String(v).trim();
  if(role==='Sender'&&r.Relationship_ID==='P2B-T-005')return '2903 Fourth Avenue; 411 Ivy Street / 2191 Fourth Avenue; 3775 Sixth Avenue';
  return 'Address not established in assembled records';
}
const recordedSourceDetails=sourceDetails;
sourceDetails=function(r){return (r.Relationship_ID==='P2B-T-005'?refugeResearchPanel():'')+recordedSourceDetails(r)};
const evidenceAreaFor=areaFor;
areaFor=function(r,role){return canonicalAreaName(evidenceAreaFor(r,role))||'Not geographically resolved'};
const canonicalRelationship=relationship;
relationship=function(r){if(!r)return canonicalRelationship(r);let html=canonicalRelationship(r);
 const oldSender=esc(r.Sender_Project_Name||r.Project_Name||'Origin unresolved'),oldReceiver=esc(r.Receiver_Project_Name||r.Receiver_Address||'Receiver not publicly resolved');
 const oldSenderAddress=esc(r.Sender_Address||r.Project_Address||'Address unresolved'),oldReceiverAddress=esc(r.Receiver_Address||'Address unresolved');
 html=html.replace(oldSender,esc(displayProjectName(r,'Sender'))).replace(oldReceiver,esc(displayProjectName(r,'Receiver'))).replace(oldSenderAddress,esc(displayAddress(r,'Sender'))).replace(oldReceiverAddress,esc(displayAddress(r,'Receiver')));if(r.Relationship_ID==='P2B-T-008')html=relationshipVisual(r)+html;return html;
};


